from taf.gnb.oam.coam.cu.utilities.m2m_interface_availability_checker import m2m_interface_availability_check
from taf.gnb.oam.coam.cu.services.licensed.fm.http_client_v1 import FMLicensedv1HttpClient
from taf.gnb.oam.coam.cu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.cu.utilities.token_storage import TokenStorage
from taf.gnb.oam.coam.cu.services.internal.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.cu.services.licensed.sec.sec_licensed_v1 import SECLicensedv1


@auto_token_refresh()
class FMLICENSEDv1:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        self.local_client = FMLicensedv1HttpClient(base_url=con_details.base_url,
                                                   connection_alias=con_details.alias)

    @m2m_interface_availability_check
    def get_active_alarms(self, timeout=None, paging=True, page_number=None, items_per_page=None, **kwargs):
        if paging:
            return self.local_client.get_active_alarms(timeout=timeout, **kwargs)
        else:
            if page_number and items_per_page:
                return self.local_client.get_active_alarms(page_number=page_number, items_per_page=items_per_page,
                                                           timeout=timeout, **kwargs)
            else:
                raise ValueError('page_number and items_per_page must be provided when paging is set to False.')


    @m2m_interface_availability_check
    def get_historical_alarms(self, timeout=None, paging=True, page_number=None, items_per_page=None, **kwargs):
        if paging:
            return self.local_client.get_historical_alarms(timeout=timeout, **kwargs)
        else:
            if page_number and items_per_page:
                return self.local_client.get_historical_alarms(page_number=page_number, items_per_page=items_per_page,
                                                               timeout=timeout, **kwargs)
            else:
                raise ValueError('page_number and items_per_page must be provided when paging is set to False.')

    @m2m_interface_availability_check
    def get_active_alarms_summary(self, timeout=None):
        return self.local_client.get_active_alarms_summary(timeout=timeout)
